"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[8978],{4856(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>d,default:()=>u,frontMatter:()=>l,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/business-pain-to-ai-lead","title":"Enterprise AI Use-Case Flow: Pain Point \u2192 Lead AI Engineer","description":"This is a practical, beginner-friendly guide to how an AI use case typically originates and travels through a large enterprise (e.g., a major bank or a national airline) until it lands with a Lead AI Engineer. It also...","source":"@site/docs/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead","permalink":"/tutorials/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":1,"frontMatter":{"title":"Enterprise AI Use-Case Flow: Pain Point \u2192 Lead AI Engineer","slug":"/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead","description":"This is a practical, beginner-friendly guide to how an AI use case typically originates and travels through a large enterprise (e.g., a major bank or a national airline) until it lands with a Lead AI Engineer. It also...","sidebar_label":"1. From business pain to AI lead","pagination_label":"1. From business pain to AI lead","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"Part overview","permalink":"/tutorials/part1-enterprise-ai-delivery/overview"},"next":{"title":"2. The intake package","permalink":"/tutorials/part1-enterprise-ai-delivery/02-intake-package"}}');var s=t(4848),a=t(8453),r=t(8172);const o=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/01-business-pain-to-ai-lead.html","route":"/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"From Pain Point \u2192 Lead AI Engineer","title":"Enterprise AI Use-Case Flow: Pain Point \u2192 Lead AI Engineer","description":"This is a practical, beginner-friendly guide to how an AI use case typically originates and travels through a large enterprise (e.g., a major bank or a national airline) until it lands with a Lead AI Engineer. It also...","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"big-picture","label":"1) Big picture"},{"id":"roles","label":"2) Roles glossary (who is who)"},{"id":"bus","label":"3) What is a BU (Business Unit) and why does it matter?"},{"id":"flow","label":"4) The typical flow: pain point \u2192 AI lead"},{"id":"example","label":"5) Concrete example (meeting-note Q&A)"},{"id":"handoff","label":"6) What arrives on the AI lead\u2019s desk (typical package)"},{"id":"first-day","label":"7) What the Lead AI Engineer does on day 1"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This is a practical, beginner-friendly guide to how an AI use case typically originates and travels through\\n      a large enterprise (e.g., a major bank or a national airline) until it lands with a <strong>Lead AI Engineer</strong>.\\n      It also explains common roles: <strong>EA</strong>, <strong>Ops</strong>, <strong>EM</strong>, <strong>GM</strong>, and <strong>Business Units (BUs)</strong>.\\n    </p>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#big-picture\\">Big picture</a></li>\\n      <li><a href=\\"#roles\\">Roles glossary</a></li>\\n      <li><a href=\\"#bus\\">What a BU is</a></li>\\n      <li><a href=\\"#flow\\">The end-to-end flow</a></li>\\n      <li><a href=\\"#example\\">Concrete example</a></li>\\n      <li><a href=\\"#handoff\\">What arrives to the AI lead</a></li>\\n      <li><a href=\\"#first-day\\">What the AI lead does on day 1</a></li>\\n    </ul>\\n\\n    <h2 id=\\"big-picture\\">1) Big picture</h2>\\n    <p>\\n      In large enterprises, AI work rarely begins with \u201clet\u2019s build an LLM.\u201d It begins with:\\n      <strong>a business pain</strong> \u2192 <strong>a formal initiative</strong> \u2192 <strong>governance and triage</strong> \u2192 <strong>delivery ownership</strong>.\\n    </p>\\n\\n    <div class=\\"callout\\">\\n      <strong>Key idea:</strong>\\n      The \u201cAI lead\u201d is usually brought in once the problem needs cross-system design (identity, data access, retrieval, model, audit),\\n      not when someone has a vague idea.\\n    </div>\\n\\n    <h2 id=\\"roles\\">2) Roles glossary (who is who)</h2>\\n    <p class=\\"small\\">Titles vary by company; these are typical meanings in Australia-based enterprises.</p>\\n\\n    <table>\\n      <thead>\\n        <tr>\\n          <th>Role</th>\\n          <th>What they do</th>\\n          <th>Why they matter to the AI project</th>\\n        </tr>\\n      </thead>\\n      <tbody>\\n        <tr>\\n          <td><strong>EA (Executive Assistant)</strong></td>\\n          <td>\\n            Supports an executive: calendars, meetings, packs, minutes, action items, briefings.\\n            Often the \u201cworkflow owner\u201d for meeting artifacts and \u201cwhat was decided.\u201d\\n          </td>\\n          <td>\\n            EAs are often power users who can define the top recurring questions and what \u201cproof\u201d looks like\\n            (citations, links, timestamps). They validate whether the tool saves real time.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Ops (Operations)</strong></td>\\n          <td>\\n            \u201cRun the business day-to-day.\u201d In airlines, this can include operations control/disruption recovery.\\n            In banks, business ops, service ops, incident/change, compliance operations, etc.\\n          </td>\\n          <td>\\n            Ops stakeholders define urgency, failure tolerance, and what a \u201cwrong answer\u201d costs.\\n            They will demand reliability, speed, and auditability.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>SME (Subject Matter Expert)</strong></td>\\n          <td>\\n            Domain expert in policy/process/operations. Knows the right sources and interpretations.\\n          </td>\\n          <td>\\n            Provides ground truth for evaluation sets, validation of answers, and \u201cwhat\u2019s allowed\u201d guidance.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Business Owner</strong></td>\\n          <td>\\n            Accountable for business outcomes: scope, priorities, success metrics, adoption.\\n            Often the person who \u201caccepts\u201d the product for business use.\\n          </td>\\n          <td>\\n            Without a business owner, pilots often become demos with no adoption. This person drives change management.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Sponsor</strong></td>\\n          <td>\\n            Senior executive champion who removes blockers and provides authority (and often budget).\\n          </td>\\n          <td>\\n            Helps secure access approvals, resolves conflicts, and unlocks resources.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>EM (Engineering Manager)</strong></td>\\n          <td>\\n            Manages engineering team delivery: staffing, planning, quality, execution, career support.\\n          </td>\\n          <td>\\n            Partner to the AI lead: ensures team capacity, delivery cadence, and operational readiness.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>GM (General Manager)</strong></td>\\n          <td>\\n            Senior leader for a function or business line (e.g., GM Digital, GM Operations, GM Data/AI).\\n            Owns strategy, budget, and high-level outcomes.\\n          </td>\\n          <td>\\n            Often the decision-maker who approves the initiative and sets constraints (risk appetite, pilot group, timelines).\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Security / IAM</strong></td>\\n          <td>\\n            Defines identity, access control, least privilege, secrets handling, network requirements.\\n          </td>\\n          <td>\\n            AI projects fail without secure-by-design access to data sources and proper audit controls.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Privacy / Legal / Risk</strong></td>\\n          <td>\\n            Ensures compliance obligations are met (PII, retention, audit, customer data restrictions).\\n          </td>\\n          <td>\\n            Defines what data the model can see and under what controls; reviews release readiness.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Data Owner</strong></td>\\n          <td>\\n            Accountable for a dataset/document corpus (approves access, usage, retention).\\n          </td>\\n          <td>\\n            Approves what documents you can ingest and how you classify/store them.\\n          </td>\\n        </tr>\\n\\n        <tr>\\n          <td><strong>Lead AI Engineer</strong></td>\\n          <td>\\n            Designs and delivers production AI systems end-to-end: data \u2192 retrieval \u2192 model \u2192 evaluation \u2192 ops.\\n          </td>\\n          <td>\\n            Converts vague ideas into an executable plan with guardrails, metrics, and reliable delivery.\\n          </td>\\n        </tr>\\n      </tbody>\\n    </table>\\n\\n    <h2 id=\\"bus\\">3) What is a BU (Business Unit) and why does it matter?</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        A <strong>Business Unit (BU)</strong> is a major organisational division that owns a slice of the business:\\n        its goals, processes, teams, data, and budgets.\\n      </p>\\n      <p>\\n        Examples (varies by company):\\n      </p>\\n      <ul>\\n        <li><strong>Airline BU examples:</strong> Network Ops, Customer Experience, Digital, Loyalty, Revenue Management</li>\\n        <li><strong>Bank BU examples:</strong> Retail Banking, Business Banking, Wealth, Risk, Technology, Operations</li>\\n      </ul>\\n      <p>\\n        Why BUs matter for your tool:\\n      </p>\\n      <ul>\\n        <li>BUs often have <strong>different data owners</strong> and <strong>different risk appetite</strong>.</li>\\n        <li>They may require <strong>different access boundaries</strong> (who can see what documents).</li>\\n        <li>Funding and sponsorship often comes from a specific BU.</li>\\n      </ul>\\n      <div class=\\"callout\\">\\n        <strong>Practical:</strong> Many initiatives start in one BU (pilot), then expand cross-BU if proven safe and valuable.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"flow\\">4) The typical flow: pain point \u2192 AI lead</h2>\\n    <p class=\\"small\\">This is the \u201centerprise conveyor belt\u201d a use case rides before it becomes a real build.</p>\\n\\n    <div class=\\"flow\\">\\n      Pain felt in BU \u2192 Quantified by EA/Ops/SME \u2192 BU manager/GM sponsorship \u2192 Brief written \u2192\\n      AI/Architecture intake gate \u2192 Security/Privacy triage \u2192 Routed to AI delivery team \u2192 Lead AI Engineer owns plan\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"step-1-pain-point-appears-inside-a-bu\\">Step 1 \u2014 Pain point appears inside a BU</h3>\\n      <p>It shows up as a workflow problem, not \u201cAI\u201d:</p>\\n      <ul>\\n        <li><strong>Time loss:</strong> execs/EAs searching meeting notes/packs/emails</li>\\n        <li><strong>Decision friction:</strong> hard to reconstruct \u201cwho said what and when\u201d</li>\\n        <li><strong>Operational risk:</strong> staff can\u2019t find latest approved guidance during incidents</li>\\n        <li><strong>Customer impact:</strong> frontline teams can\u2019t find policy answers quickly</li>\\n      </ul>\\n      <p class=\\"small\\">The BU feels it because it directly impacts throughput and outcomes.</p>\\n\\n      <h3 id=\\"step-2-someone-makes-it-real-ea-ops-compliance\\">Step 2 \u2014 Someone makes it real (EA/Ops/Compliance)</h3>\\n      <p>\\n        This is the trigger point. Typical voices:\\n      </p>\\n      <ul>\\n        <li><strong>EA:</strong> \u201cWe spend 5\u201310 hours/week per exec chasing meeting artifacts and compiling answers.\u201d</li>\\n        <li><strong>Ops:</strong> \u201cDuring disruptions/incidents, information retrieval is the bottleneck.\u201d</li>\\n        <li><strong>Risk/Compliance:</strong> \u201cWe spend days reconstructing evidence and decision trails.\u201d</li>\\n      </ul>\\n      <div class=\\"callout\\">\\n        <strong>Why EAs matter:</strong> they live inside the executive workflow and define what \u201cuseful output\u201d looks like.<br>\\n        <strong>Why Ops matters:</strong> they define urgency and what \u201cwrong answer\u201d costs.\\n      </div>\\n\\n      <h3 id=\\"step-3-the-bu-converts-pain-into-an-initiative\\">Step 3 \u2014 The BU converts pain into an initiative</h3>\\n      <p>\\n        The BU manager or GM (often with a sponsor) decides: \u201cthis is worth pursuing.\u201d It becomes:\\n      </p>\\n      <ul>\\n        <li>a roadmap item (internal product)</li>\\n        <li>a transformation initiative (knowledge management / AI uplift)</li>\\n        <li>a risk/governance program (auditability)</li>\\n        <li>an ops improvement effort (incident response)</li>\\n      </ul>\\n      <p class=\\"small\\">\\n        A short brief is drafted: problem, users, constraints, desired outcome, rough ROI.\\n      </p>\\n\\n      <h3 id=\\"step-4-ai-intake-architecture-governance-triage\\">Step 4 \u2014 AI intake / architecture / governance triage</h3>\\n      <p>\\n        Enterprises run gate checks before they invest:\\n      </p>\\n      <ul>\\n        <li>Is it actually AI, or should we fix search/metadata/source systems first?</li>\\n        <li>Do we have data access rights and clear data ownership?</li>\\n        <li>What is the sensitivity classification (PII, strategy, HR)?</li>\\n        <li>What\u2019s the failure risk (wrong answers) and what controls are required?</li>\\n        <li>Can success be measured?</li>\\n      </ul>\\n      <div class=\\"warn\\">\\n        <strong>Common outcome:</strong> \u201cPilot only\u201d with a tightly approved corpus and strict access controls.\\n      </div>\\n\\n      <h3 id=\\"step-5-work-is-routed-to-delivery-ai-lead-gets-it\\">Step 5 \u2014 Work is routed to delivery (AI lead gets it)</h3>\\n      <p>\\n        Now it lands as an actionable request, usually with constraints like:\\n      </p>\\n      <ul>\\n        <li>\u201cWe need citations and audit logs.\u201d</li>\\n        <li>\u201cAccess must be restricted by user / business unit / group membership.\u201d</li>\\n        <li>\u201cWe must meet security/privacy controls.\u201d</li>\\n      </ul>\\n      <p class=\\"small\\">\\n        The AI lead gets it because it spans identity, ingestion, retrieval, model behavior, evaluation, and operations.\\n      </p>\\n    </div>\\n\\n    <h2 id=\\"example\\">5) Concrete example (meeting-note Q&amp;A)</h2>\\n    <div class=\\"card\\">\\n      <p><strong>Problem:</strong> Exec asks \u201cWhat did Chandima mention about no meeting on 1 Dec?\u201d</p>\\n      <p><strong>Current state:</strong> EA manually searches packs/minutes/emails and compiles a reply.</p>\\n      <p><strong>Desired state:</strong> tool returns:</p>\\n      <ul>\\n        <li>short answer</li>\\n        <li>citation: exact snippet from the 1 Dec meeting note + link</li>\\n        <li>safe behavior: if not found, say so and suggest next best query</li>\\n      </ul>\\n      <div class=\\"callout\\">\\n        <strong>EA success signal:</strong> \u201cI can copy/paste this to the exec and it has evidence.\u201d<br>\\n        <strong>Ops success signal:</strong> \u201cIt\u2019s fast, reliable, and never guesses when evidence is missing.\u201d\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"handoff\\">6) What arrives on the AI lead\u2019s desk (typical package)</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li><strong>Brief:</strong> the business problem, users, constraints</li>\\n        <li><strong>Sponsor:</strong> a GM or senior leader backing it</li>\\n        <li><strong>Business owner:</strong> accountable for adoption and success metrics</li>\\n        <li><strong>Data owners:</strong> who approves the corpus (meeting notes/packs)</li>\\n        <li><strong>Security/privacy constraints:</strong> what must be enforced</li>\\n      </ul>\\n      <p class=\\"small\\">\\n        At this stage, the AI lead is expected to turn this into: scope, architecture, pilot plan, eval plan, and operating model.\\n      </p>\\n    </div>\\n\\n    <h2 id=\\"first-day\\">7) What the Lead AI Engineer does on day 1</h2>\\n    <div class=\\"card\\">\\n      <h3 id=\\"day-1-outputs-what-lead-level-looks-like\\">Day 1 outputs (what \u201clead-level\u201d looks like)</h3>\\n      <ul>\\n        <li><strong>Problem reframing:</strong> \u201cCited Q&amp;A over approved meeting corpus, scoped by identity.\u201d</li>\\n        <li><strong>MVP slice:</strong> one BU/corpus + top 1\u20132 question types</li>\\n        <li><strong>Access model:</strong> who can see what (group gating + document corpus allowlist)</li>\\n        <li><strong>Success metrics:</strong> citation correctness, groundedness, time saved</li>\\n        <li><strong>Evaluation plan:</strong> a \u201cgolden set\u201d of questions + release gates</li>\\n        <li><strong>Delivery plan:</strong> team lanes + dependencies + timeline</li>\\n      </ul>\\n\\n      <div class=\\"callout\\">\\n        <strong>Key lead move:</strong> co-design with EAs and Ops early. They define workflow reality and failure tolerance.\\n      </div>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Companion artifacts</strong>\\n      The working pack for this stage should include (1) a stakeholder map for\\n      EA, Operations, Security, Privacy, the Data Owner, and the GM, including\\n      each role\'s concerns and common objections, and (2) a sample intake brief\\n      plus AI lead response document for the meeting-notes Q&amp;A pilot.\\n    </div>\\n  </div>"}'),l={title:"Enterprise AI Use-Case Flow: Pain Point \u2192 Lead AI Engineer",slug:"/part1-enterprise-ai-delivery/01-business-pain-to-ai-lead",description:"This is a practical, beginner-friendly guide to how an AI use case typically originates and travels through a large enterprise (e.g., a major bank or a national airline) until it lands with a Lead AI Engineer. It also...",sidebar_label:"1. From business pain to AI lead",pagination_label:"1. From business pain to AI lead",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function g(e){return(0,s.jsx)(r.A,{content:o})}function u(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(g,{...e})}):g()}}}]);